import { expect, test } from './fixtures';

/**
 * Design conformance, in a real browser.
 *
 * Generated by design-tools/gen-conformance.mjs from the design handoff, and
 * checked in deliberately. These assert the frame and the measurements — the
 * part visual review reliably misses. The numbers are hand-set in the mock and
 * do not round to a spacing ladder, so a later pass that tidies them would
 * silently redraw the screen. That is what this is here to stop; it is not
 * pedantry.
 *
 * Source: doc/handoffs/extensions-select/Tablet-Selecting.dc.html
 * Extracted at 2026-11-09T19:10:05.119Z at 1440x2400.
 *
 * It runs in the browse project (its name) against tests/browse-setup.ts's
 * fake engine, whose installed rows and bulk bar this is: the world's packages
 * have no repository listing left, so they are all 01 — NEEDS A HAND. The
 * other two section labels are the same `.label`; the frame's map does not
 * repeat them.
 *
 * Regenerating overwrites this file. Hand edits belong in a sibling spec.
 */

const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

// The board is the tablet's, 1280x800 (Tablet-Selecting); the browse project's
// own is the tablet at 800x1280, so this file sets the drawn one.
test.use({ viewport: { width: 1280, height: 800 } });

const SEL = {
	frame: 'body',
	region1: 'nav[aria-label="Extensions"] .tab:nth-child(1)',
	region2: 'nav[aria-label="Extensions"] .tab:nth-child(2)',
	region3: 'nav[aria-label="Extensions"] .tab:nth-child(3)',
	region4: 'div.label:has-text("01 — NEEDS A HAND")',
	region5: 'div.label:has-text("01 — NEEDS A HAND") .r',
	region10: '.bulk .swr',
	region11: '.bulk .swr > *:nth-child(1)',
	region12: '.bulk .swr > *:nth-child(2)',
	region13: '.bulk .swr > *:nth-child(3)',
	region14: '.bulk .swr > *:nth-child(4)'
};

test('screen: frame matches the handoff', async ({ page }) => {
	await page.goto(`${base}/browse/extensions?select=1&pkg=e2e.open&pkg=e2e.anime&pkg=ln%3Ashelf`);
	await expect(page.locator(SEL.frame)).toBeVisible();

	const frameStyle = await page.locator(SEL.frame).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(frameStyle.display).toBe('block');
});

test('screen: region1 matches the handoff', async ({ page }) => {
	await page.goto(`${base}/browse/extensions?select=1&pkg=e2e.open&pkg=e2e.anime&pkg=ln%3Ashelf`);
	await expect(page.locator(SEL.region1)).toBeVisible();

	const region1Style = await page.locator(SEL.region1).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			alignItems: cs.alignItems,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			paddingRight: cs.paddingRight,
			paddingLeft: cs.paddingLeft,
			borderRightWidth: cs.borderRightWidth,
			fontSize: cs.fontSize,
			fontWeight: cs.fontWeight,
			lineHeight: cs.lineHeight
		};
	});
	expect(region1Style.display).toBe('flex');
	expect(region1Style.alignItems).toBe('center');
	expect(region1Style.rowGap).toBe('8px');
	expect(region1Style.columnGap).toBe('8px');
	expect(region1Style.paddingRight).toBe('16px');
	expect(region1Style.paddingLeft).toBe('16px');
	expect(region1Style.borderRightWidth).toBe('1px');
	expect(region1Style.fontSize).toBe('14px');
	expect(region1Style.fontWeight).toBe('500');
	expect(region1Style.lineHeight).toBe('16.8px');
});

