test('screen: region10 matches the handoff', async ({ page }) => {
	await page.goto(`${base}/browse/extensions?select=1&pkg=e2e.open&pkg=e2e.anime&pkg=ln%3Ashelf`);
	await expect(page.locator(SEL.region10)).toBeVisible();

	// authored as: 213.328px 213.328px 213.328px 213.344px 213.328px 213.328px
	const region10Tracks = (
		(await page
			.locator(SEL.region10)
			.evaluate((node) => getComputedStyle(node).gridTemplateColumns)) as string
	).split(' ');
	expect(region10Tracks).toHaveLength(6);
	expect(Math.round(parseFloat(region10Tracks[0]))).toBe(213);
	expect(Math.round(parseFloat(region10Tracks[1]))).toBe(213);
	expect(Math.round(parseFloat(region10Tracks[2]))).toBe(213);
	expect(Math.round(parseFloat(region10Tracks[3]))).toBe(213);
	expect(Math.round(parseFloat(region10Tracks[4]))).toBe(213);
	expect(Math.round(parseFloat(region10Tracks[5]))).toBe(213);

	const region10Style = await page.locator(SEL.region10).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(region10Style.display).toBe('grid');
});

